import sys,json,tempfile,time,queue,hashlib,subprocess
from pathlib import Path
sys.path.insert(0,str(Path.cwd()/'scripts'))
from semantic_lsp import LspProcess,MeasurementError
class Trace(LspProcess):
 def __init__(self,*args):self.raw=[];super().__init__(*args)
 def _dispatch(self,body,received_ns):self.raw.append(json.loads(body));return super()._dispatch(body,received_ns)
 def expected_error(self,method,params):
  request_id,_=self.send_request(self.prepare_request(method,params));deadline=time.monotonic()+30
  while True:
   body,received_ns=self.messages.get(timeout=max(0.01,deadline-time.monotonic()))
   if isinstance(body,Exception) or body is None:raise MeasurementError('transport ended during expected error')
   message=json.loads(body)
   if message.get('id')==request_id:
    self.raw.append(message);del self.pending[request_id]
    assert 'error' in message,message
    return message
   self._dispatch(body,received_ns)
 def current_diagnostics(self,uri,version):
  deadline=time.monotonic()+30
  while self.diagnostics.get(uri,{}).get('version')!=version:self._receive(deadline)
  return self.diagnostics[uri]
def offset(text,position):
 lines=text.splitlines(keepends=True);line=position['line'];units=position['character']
 return sum(map(len,lines[:line]))+len(lines[line].encode('utf-16-le')[:units*2].decode('utf-16-le'))
def workspace_edits(edit,uri,version):
 if 'documentChanges' in edit:
  changes=edit['documentChanges'];assert len(changes)==1,edit
  change=changes[0];assert change['textDocument']=={'uri':uri,'version':version},change
  return change['edits']
 assert set(edit)=={'changes'} and set(edit['changes'])=={uri},edit
 return edit['changes'][uri]
def apply_edit(text,edit,uri,version):
 spans=[(offset(text,e['range']['start']),offset(text,e['range']['end']),e['newText']) for e in workspace_edits(edit,uri,version)]
 for start,end,replacement in sorted(spans,reverse=True):text=text[:start]+replacement+text[end:]
 return text
binary=Path('/workspace/target/semantic-approved-126952f6d048/debug/bend2-lsp')
report={'binary_sha256':hashlib.sha256(binary.read_bytes()).hexdigest(),'compiler':'/tmp/semantic-review-native/bend/bin/bend','cases':[]}
for kind in ['malformed-header','invalid-import']:
 with tempfile.TemporaryDirectory(prefix='review-recovery-'+kind+'-') as temporary:
  workspace=Path(temporary);root=workspace/'main.bend';uri=root.as_uri()
  if kind=='malformed-header':
   source='import Base\ndef add(target: U32) -> U32:\n  target\ndef main: U32\n  add(1)\n'
   repaired=source.replace('def main: U32','def main() -> U32:')
   position={'line':4,'character':4};expected={'uri':uri,'range':{'start':{'line':1,'character':4},'end':{'line':1,'character':7}}}
  else:
   module=workspace/'module';module.write_text('import Base\ndef value() -> U32:\n  3\n')
   valid_module=workspace/'module.bend';valid_module.write_text(module.read_text())
   source='import Base\nimport ./module as Module\ndef main() -> U32:\n  Module.value()\n'
   repaired=source.replace('./module as','./module.bend as');position={'line':3,'character':11}
  root.write_text(source);case={'kind':kind,'source':source};client=Trace(binary,workspace)
  try:
   client.compiler_path=report['compiler'];client.settings={'bend2-lsp':{'compilerPath':client.compiler_path,'compilerArguments':[]}}
   client.initialize();client.notify('textDocument/didOpen',{'textDocument':{'uri':uri,'languageId':'bend','version':1,'text':source}})
   case['version1_diagnostics']=client.current_diagnostics(uri,1)
   assert any(d.get('code')=='compiler' and d.get('severity')==1 for d in case['version1_diagnostics']['diagnostics']),case
   case['version1_definition']=client.request('textDocument/definition',{'textDocument':{'uri':uri},'position':position})[0]
   if kind=='malformed-header':
    assert case['version1_definition']==expected,case
    case['version1_hover']=client.request('textDocument/hover',{'textDocument':{'uri':uri},'position':position})[0]
    assert 'add' in case['version1_hover']['contents']['value'],case
   else:
    assert case['version1_definition'] is None,case
    case['editor_links']=client.request('textDocument/documentLink',{'textDocument':{'uri':uri}})[0]
    link=next(link for link in case['editor_links'] if link['range']['start']['line']==1)
    assert link['target']==module.as_uri() and link['data']['uncertain'] is True,case
    case['editor_path_definition']=client.request('textDocument/definition',{'textDocument':{'uri':uri},'position':{'line':1,'character':10}})[0]
    assert case['editor_path_definition']['uri']==module.as_uri(),case
   client.notify('textDocument/didChange',{'textDocument':{'uri':uri,'version':2},'contentChanges':[{'text':repaired}]})
   case['version2_diagnostics']=client.current_diagnostics(uri,2)
   assert case['version2_diagnostics']['diagnostics']==[],case
   case['version2_definition']=client.request('textDocument/definition',{'textDocument':{'uri':uri},'position':position})[0]
   if kind=='malformed-header':assert case['version2_definition']==expected,case
   else:assert case['version2_definition']=={'uri':valid_module.as_uri(),'range':{'start':{'line':1,'character':4},'end':{'line':1,'character':9}}},case
   client.finish();case['exit']=client.process.returncode;assert case['exit']==0,case
   root.write_text(repaired);checked=subprocess.run([report['compiler'],str(root)],capture_output=True,text=True,timeout=30)
   case['direct_genuine_compiler_check']={'returncode':checked.returncode,'stdout':checked.stdout,'stderr':checked.stderr};assert checked.returncode==0,case
  except BaseException:
   case['raw_messages']=client.raw;case['stderr']=client.stderr_tail();print(json.dumps({'completed':report,'failed':case},ensure_ascii=False,indent=2),file=sys.stderr);raise
  finally:case['raw_messages']=client.raw;case['stderr']=client.stderr_tail();client.close()
  report['cases'].append(case)
print(json.dumps(report,ensure_ascii=False,indent=2))

